1→import type { SessionStore } from "./sessionStore";

export type SessionEndReason = "expired" | "logout";

/**
 * Owns the in-memory token and serializes every access to the encrypted store.
 *
 * A protected response may arrive after another login has started. Keeping store
 * operations in invocation order and checking the token that originated a 401
10→ * prevents that stale response from deleting the newly established session.
 */
export class SessionManager {
  private token: string | null = null;
  private operationTail: Promise<void> = Promise.resolve();
  private readonly clearOperations = new Map<string | null, Promise<void>>();
  private clearPending = false;

  constructor(
    private readonly store: SessionStore,
20→    private readonly onCleared: (reason: SessionEndReason) => void,
  ) {}

  currentToken(): string | null {
    return this.token;
  }

  restore(): Promise<{ token: string | null; readFailed: boolean }> {
    return this.enqueue(async () => {
      if (this.clearPending) {
30→        await this.tryClearStoredToken();
        return { token: null, readFailed: false };
      }
      try {
        const token = await this.store.readToken();
        this.token = token;
        return { token, readFailed: false };
      } catch {
        this.token = null;
        return { token: null, readFailed: true };
40→      }
    });
  }

  establish(token: string): Promise<void> {
    return this.enqueue(async () => {
      await this.store.saveToken(token);
      this.token = token;
      // A successful write supersedes any failed deletion of an older session.
      this.clearPending = false;
50→    });
  }

  /**
   * Clears the active session at most once. When expectedToken is supplied, the
   * request is ignored unless that exact session is still current when its turn
   * in the store-operation queue arrives.
   */
  clearSingleton(
    expectedToken?: string,
60→    reason: SessionEndReason = "expired",
  ): Promise<void> {
    // Capture the current session at invocation time for callers that do not
    // provide it. Resolving it later, after a queued establish(), could clear
    // the replacement session instead of the one that triggered this action.
    const targetToken = expectedToken ?? this.token;
    const key = targetToken;
    const current = this.clearOperations.get(key);
    if (current) return current;

70→    const operation = this.enqueue(async () => {
      if (targetToken !== null && this.token !== targetToken) return;

      if (targetToken === null) {
        if (this.clearPending) await this.tryClearStoredToken();
        return;
      }

      this.token = null;
      this.clearPending = true;
80→      this.onCleared(reason);
      await this.tryClearStoredToken();
    });
    this.clearOperations.set(key, operation);
    void operation.finally(() => {
      if (this.clearOperations.get(key) === operation) this.clearOperations.delete(key);
    });
    return operation;
  }

90→  retryPendingClear(): Promise<void> {
    return this.enqueue(async () => {
      if (this.clearPending && this.token === null) await this.tryClearStoredToken();
    });
  }

  private async tryClearStoredToken(): Promise<void> {
    try {
      await this.store.clearToken();
      this.clearPending = false;
100→    } catch {
      // Keep the deletion pending for a safe retry on the next foreground event.
    }
  }

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.operationTail.then(operation);
    this.operationTail = result.then(
      () => undefined,
      () => undefined,
110→    );
    return result;
  }
}

1→import * as SecureStore from "expo-secure-store";

const TOKEN_KEY = "orbe.session-token.v1";

export const sessionStore = {
  readToken(): Promise<string | null> {
    return SecureStore.getItemAsync(TOKEN_KEY);
  },
  saveToken(token: string): Promise<void> {
10→    return SecureStore.setItemAsync(TOKEN_KEY, token);
  },
  clearToken(): Promise<void> {
    return SecureStore.deleteItemAsync(TOKEN_KEY);
  },
};

export type SessionStore = typeof sessionStore;

