const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const INVALID_MESSAGE = "Email o contraseña incorrectos.";
const CONNECTION_MESSAGE = "No se pudo conectar. Revisá tu conexión e intentá nuevamente.";

interface LoginScreenProps {
  api: ApiClient;
20→  onAuthenticated: (token: string) => Promise<void>;
  initialNotice?: string | null;
}

export function LoginScreen({ api, initialNotice = null, onAuthenticated }: LoginScreenProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [emailError, setEmailError] = useState<string | null>(null);
  const [passwordError, setPasswordError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(initialNotice);
30→  const [submitting, setSubmitting] = useState(false);
  const [retryUntil, setRetryUntil] = useState<number | null>(null);
  const [retrySeconds, setRetrySeconds] = useState(0);
  const inFlight = useRef(false);
  const emailShapeValid = EMAIL_SHAPE.test(email.trim());
  const formValid = emailShapeValid && password.length > 0;
  const submitDisabled = !formValid || submitting || retrySeconds > 0;

  useEffect(() => {
    if (retryUntil === null) return;
40→    const update = () => {
      const seconds = Math.max(0, Math.ceil((retryUntil - Date.now()) / 1000));
      setRetrySeconds(seconds);
      if (seconds === 0) setRetryUntil(null);
    };
    update();
    const timer = setInterval(update, 250);
    return () => clearInterval(timer);
  }, [retryUntil]);

50→  async function submit() {
    if (inFlight.current || retrySeconds > 0) return;
    const normalizedForValidation = email.trim();
    const nextEmailError = normalizedForValidation.length === 0
      ? "Ingresá tu email."
      : !EMAIL_SHAPE.test(normalizedForValidation)
        ? "Ingresá un email válido."
        : null;
    const nextPasswordError = password.length === 0 ? "Ingresá tu contraseña." : null;
    setEmailError(nextEmailError);
60→    setPasswordError(nextPasswordError);
    setNotice(null);
    if (nextEmailError || nextPasswordError) return;

    inFlight.current = true;
    setSubmitting(true);
    try {
      const session = await api.login(email, password);
      await onAuthenticated(session.token);
    } catch (error) {
70→      if (error instanceof ApiError && error.code === "INVALID_CREDENTIALS") {
        setNotice(INVALID_MESSAGE);
        setPassword("");
      } else if (error instanceof ApiError && error.code === "RATE_LIMITED") {
        const raw = error.details?.retryAfterSeconds;
        const seconds = typeof raw === "number" && Number.isInteger(raw) && raw >= 0 ? raw : 1;
        setRetrySeconds(seconds);
        setRetryUntil(Date.now() + seconds * 1000);
      } else if (error instanceof ApiError && error.code === "VALIDATION_ERROR") {
        const issues = validationIssues(error);
80→        const emailMessages = issues.filter((issue) => issue.field === "email").map((issue) => issue.message);
        const passwordMessages = issues.filter((issue) => issue.field === "password").map((issue) => issue.message);
        const formMessages = issues
          .filter((issue) => issue.field === "form" || issue.field === "body")
          .map((issue) => issue.message);
        setEmailError(emailMessages.length > 0 ? emailMessages.join("\n") : null);
        setPasswordError(passwordMessages.length > 0 ? passwordMessages.join("\n") : null);
        setNotice(
          formMessages.length > 0
            ? formMessages.join("\n")
90→            : issues.length === 0
              ? "Revisá los datos ingresados."
              : null,
        );
      } else if (error instanceof NetworkError || (error instanceof ApiError && error.code === "INTERNAL_ERROR")) {
        setNotice(CONNECTION_MESSAGE);
      } else {
        setNotice(CONNECTION_MESSAGE);
      }
    } finally {
100→      inFlight.current = false;
      setSubmitting(false);
    }
  }

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === "ios" ? "padding" : undefined}
      style={styles.shell}
    >
110→      <View style={styles.brand}>
        <Text style={styles.mark}>O</Text>
        <Text style={styles.brandName}>ORBE</Text>
      </View>
      <View style={styles.hero}>
        <Text style={styles.eyebrow}>EXCHANGE · SEPOLIA</Text>
        <Text style={styles.title}>Tu acceso al mercado, sin ruido.</Text>
        <Text style={styles.subtitle}>Ingresá para consultar tu dirección de depósito de testnet.</Text>
      </View>
      <View style={styles.card}>
120→        <Text style={styles.cardTitle}>Ingresá a tu cuenta</Text>
        {notice ? <Text accessibilityRole="alert" style={styles.notice}>{notice}</Text> : null}
        {retrySeconds > 0 ? (
          <Text accessibilityRole="text" accessibilityLiveRegion="polite" style={styles.notice}>
            Demasiados intentos. Reintentá en {retrySeconds} s.
          </Text>
        ) : null}
        <Text style={styles.label}>Email</Text>
        <TextInput
          accessibilityLabel="Email"
130→          autoCapitalize="none"
          autoComplete="email"
          autoCorrect={false}
          inputMode="email"
          onChangeText={(value) => { setEmail(value); setEmailError(null); }}
          onBlur={() => {
            const normalized = email.trim();
            setEmailError(
              normalized.length === 0
                ? "Ingresá tu email."
140→                : EMAIL_SHAPE.test(normalized)
                  ? null
                  : "Ingresá un email válido.",
            );
          }}
          style={[styles.input, emailError ? styles.inputError : null]}
          value={email}
        />
        {emailError ? <Text accessibilityRole="alert" style={styles.fieldError}>{emailError}</Text> : null}
        <Text style={styles.label}>Contraseña</Text>
150→        <TextInput
          accessibilityLabel="Contraseña"
          autoCapitalize="none"
          autoComplete="current-password"
          autoCorrect={false}
          onChangeText={(value) => { setPassword(value); setPasswordError(null); }}
          onBlur={() => setPasswordError(password.length === 0 ? "Ingresá tu contraseña." : null)}
          secureTextEntry
          style={[styles.input, passwordError ? styles.inputError : null]}
          value={password}
160→        />
        {passwordError ? <Text accessibilityRole="alert" style={styles.fieldError}>{passwordError}</Text> : null}
        <Pressable
          accessibilityRole="button"
          disabled={submitDisabled}
          onPress={() => void submit()}
          style={({ pressed }) => [styles.button, pressed && styles.pressed, submitDisabled && styles.disabled]}
        >
          {submitting ? <ActivityIndicator color="#07130f" /> : <Text style={styles.buttonText}>Ingresar</Text>}
        </Pressable>
170→      </View>
      <Text style={styles.footer}>ETH / USDC-MOCK · LOS ACTIVOS DE TESTNET NO TIENEN VALOR REAL</Text>
    </KeyboardAvoidingView>
  );
}

