import { AppState, type AppStateStatus, StyleSheet, Text, View } from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { StatusBar } from "expo-status-bar";
import { ApiClient } from "./api";
import { API_BASE_URL } from "./config";
import { DepositScreen } from "./DepositScreen";
import { LoginScreen } from "./LoginScreen";
import { PrivateSocket, type ConnectionState } from "./privateSocket";
10→import { SessionManager, type SessionEndReason } from "./session";
import { sessionStore, type SessionStore } from "./sessionStore";

type Phase = "boot" | "anonymous" | "authenticated";

export interface AppProps {
  apiBaseUrl?: string;
  store?: SessionStore;
  fetchImpl?: typeof fetch;
  socketFactory?: (url: string) => WebSocket;
20→}

export function App({
  apiBaseUrl = API_BASE_URL,
  store = sessionStore,
  fetchImpl,
  socketFactory,
}: AppProps) {
  const [phase, setPhase] = useState<Phase>("boot");
  const [token, setToken] = useState<string | null>(null);
30→  const [privateConnection, setPrivateConnection] = useState<ConnectionState>("disconnected");
  const [privateOverlay, setPrivateOverlay] = useState(AppState.currentState !== "active");
  const [loginNotice, setLoginNotice] = useState<string | null>(null);
  const readFailed = useRef(false);
  const phaseRef = useRef<Phase>(phase);
  const socketRef = useRef<PrivateSocket | null>(null);
  phaseRef.current = phase;

  const managerRef = useRef<SessionManager | null>(null);
  if (managerRef.current === null) {
40→    managerRef.current = new SessionManager(store, (reason: SessionEndReason) => {
      socketRef.current?.stop();
      socketRef.current = null;
      setToken(null);
      setLoginNotice(reason === "expired" ? "Tu sesión expiró, ingresá nuevamente." : null);
      setPhase("anonymous");
    });
  }
  const manager = managerRef.current;

50→  const api = useMemo(() => new ApiClient({
    baseUrl: apiBaseUrl,
    fetchImpl,
    onUnauthenticated: (expiredToken) => { void manager.clearSingleton(expiredToken, "expired"); },
  }), [apiBaseUrl, fetchImpl, manager]);

  async function restore() {
    const restored = await manager.restore();
    readFailed.current = restored.readFailed;
    if (restored.token) {
60→      setToken(restored.token);
      setPhase("authenticated");
    } else {
      setPhase("anonymous");
    }
  }

  useEffect(() => {
    void restore();
    return () => socketRef.current?.stop();
70→  }, []);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (next: AppStateStatus) => {
      const active = next === "active";
      setPrivateOverlay(!active);
      if (!active) {
        socketRef.current?.stop();
      } else {
        void manager.retryPendingClear();
80→        if (phaseRef.current === "authenticated") {
          socketRef.current?.start();
        } else if (readFailed.current) {
          void restore();
        }
      }
    });
    return () => subscription?.remove();
  }, []);

90→  useEffect(() => {
    if (phase !== "authenticated" || token === null) return;
    const socket = new PrivateSocket({
      baseUrl: apiBaseUrl,
      token,
      socketFactory,
      onStateChange: setPrivateConnection,
      onUnauthenticated: (expiredToken) => { void manager.clearSingleton(expiredToken, "expired"); },
    });
    socketRef.current = socket;
100→    if (AppState.currentState === "active") socket.start();
    return () => {
      socket.stop();
      if (socketRef.current === socket) socketRef.current = null;
    };
  }, [apiBaseUrl, manager, phase, socketFactory, token]);

  async function authenticated(nextToken: string) {
    await manager.establish(nextToken);
    readFailed.current = false;
110→    setLoginNotice(null);
    setToken(nextToken);
    setPhase("authenticated");
  }

  async function logout() {
    const current = manager.currentToken();
    const remoteLogout = current ? api.invalidateRemoteSession(current) : Promise.resolve();
    await manager.clearSingleton(current ?? undefined, "logout");
    void remoteLogout;
120→  }

  return (
    <SafeAreaProvider>
      <StatusBar style="light" />
      <SafeAreaView edges={["top", "bottom"]} style={styles.safeArea}>
        {phase === "boot" ? (
          <View style={styles.boot}>
            <Text style={styles.bootMark}>O</Text>
            <Text style={styles.bootText}>ORBE</Text>
130→          </View>
        ) : phase === "anonymous" ? (
          <LoginScreen api={api} initialNotice={loginNotice} onAuthenticated={authenticated} />
        ) : token ? (
          <DepositScreen
            api={api}
            connectionState={privateConnection}
            onLogout={logout}
            token={token}
          />
140→        ) : null}
        {phase === "authenticated" && privateOverlay ? (
          <View accessibilityLabel="Contenido protegido" style={styles.privacyOverlay} testID="privacy-overlay">
            <Text style={styles.overlayMark}>O</Text>
          </View>
        ) : null}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}
150→
const styles = StyleSheet.create({
