  boot: { flex: 1, backgroundColor: "#07110e", alignItems: "center", justifyContent: "center" },
  bootMark: { color: "#07110e", backgroundColor: "#b7f397", width: 58, height: 58, borderRadius: 29, textAlign: "center", lineHeight: 58, fontSize: 28, fontWeight: "900" },
  bootText: { color: "#f1faf5", fontWeight: "800", fontSize: 18, letterSpacing: 5, marginTop: 14 },
